58	// WorktreeChangedNames returns the names `git diff --name-only <base>` would
59	// give against the work tree, without writing the index: the paths changed
60	// between base and HEAD, and the paths the work tree changes from HEAD. A
61	// path in both is listed only when the work tree still differs from base, as
62	// the diff would (compared by content, as `git hash-object` reads it).
63	func WorktreeChangedNames(root, base string, diffArgs ...string) ([]string, error) {
64		committed := map[string]bool{}
65		var names []string
66		if base != "" && base != "HEAD" {
67			args := append([]string{"-C", root}, diffArgs...)
68			args = append(args, "diff", "--name-only", "-z", "--no-renames", base, "HEAD", "--")
69			out, err := RawGit(args...).Output()
70			if err != nil {
71				return nil, fmt.Errorf("pose: git diff %s HEAD failed: %w", base, err)
72			}
73			for _, name := range strings.Split(string(out), "\x00") {
74				if name != "" {
75					committed[name] = true
76				}
77			}
78		}
79		changes, err := WorktreeChanges(root)
80		if err != nil {
81			return nil, err
82		}
83		inWorktree := map[string]bool{}
84		for _, c := range changes {
85			inWorktree[c.Path] = true
86			if !committed[c.Path] {
87				names = append(names, c.Path)
88				continue
89			}
90			same, err := worktreeMatchesCommit(root, base, c.Path)
91			if err != nil {
92				return nil, err
93			}
94			if !same {
95				names = append(names, c.Path)
96			}
97		}
98		for name := range committed {
99			if !inWorktree[name] {
100				names = append(names, name)
101			}
102		}
103		sort.Strings(names)
104		return names, nil
105	}
