107	// worktreeMatchesCommit reports whether path in the work tree has the
108	// content it has at commit, both absent counting as a match; nothing is
109	// written (hash-object without -w).
110	func worktreeMatchesCommit(root, commit, path string) (bool, error) {
111		want, werr := RawGit("-C", root, "rev-parse", "--verify", "-q", commit+":"+path).Output()
112		full := filepath.Join(root, filepath.FromSlash(path))
113		info, err := os.Lstat(full)
114		if err != nil {
115			if os.IsNotExist(err) {
116				return werr != nil, nil
117			}
118			return false, err
119		}
120		if werr != nil {
121			return false, nil
122		}
123		var got []byte
124		if info.IsDir() {
125			// A submodule: its checked-out commit is what the gitlink records.
126			got, err = RawGit("-C", full, "rev-parse", "HEAD").Output()
127		} else {
128			got, err = RawGit("-C", root, "hash-object", "--path="+path, "--", path).Output()
129		}
130		if err != nil {
131			return false, fmt.Errorf("pose: git hash-object %s failed: %w", path, err)
132		}
133		return strings.TrimSpace(string(got)) == strings.TrimSpace(string(want)), nil
134	}
